import{_ as a,o as l,c as o,a2 as r}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা","description":"","frontmatter":{},"headers":[],"relativePath":"bn/0034-欧洲大陆社会型文明.md","filePath":"bn/0034-欧洲大陆社会型文明.md"}'),i={name:"bn/0034-欧洲大陆社会型文明.md"};function e(n,t,s,d,h,u){return l(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতা" tabindex="-1">ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা <a class="header-anchor" href="#ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতা" aria-label="Permalink to &quot;ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>34</td></tr><tr><td>মডিউল</td><td>সভ্যতার টাইপোলজি এবং সামাজিক ব্যবস্থা</td></tr><tr><td>মূল কীওয়ার্ড</td><td>ইউরোপীয় মহাদেশ, সামাজিক বাজার, মজুরি-মূলধন যৌথ সিদ্ধান্ত, সমিতিবাদ, আলোচনামূলক গণতন্ত্র</td></tr></tbody></table><h2 id="_1-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-উৎপত্তি-এবং-মূল-দর্শন" tabindex="-1">1. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার উৎপত্তি এবং মূল দর্শন <a class="header-anchor" href="#_1-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-উৎপত্তি-এবং-মূল-দর্শন" aria-label="Permalink to &quot;1. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার উৎপত্তি এবং মূল দর্শন&quot;">​</a></h2><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা হল পাঁচটি সিম্বায়োসিস সভ্যতার টাইপোলজির মধ্যে সবচেয়ে সামাজিক বাজার অর্থনীতি এবং সমিতিবাদী বৈশিষ্ট্যযুক্ত একটি, এবং এর উৎপত্তি বাস্তব বিশ্বের ইউরোপীয় মহাদেশীয় দেশগুলির (প্রধানত জার্মানি, ফ্রান্স, নেদারল্যান্ডস, অস্ট্রিয়া ইত্যাদি) সামাজিক মডেল পর্যন্ত খুঁজে পাওয়া যায়। ইউরোপীয় মহাদেশীয় দেশগুলি দীর্ঘমেয়াদী উন্নয়নের মধ্যে, &quot;সামাজিক বাজার অর্থনীতি&quot;, &quot;মজুরি-মূলধন যৌথ সিদ্ধান্ত&quot;, &quot;সমিতিবাদ&quot; কে কেন্দ্র করে সভ্যতার বৈশিষ্ট্য গঠন করেছে, যা যুক্তরাজ্য-মার্কিন স্বাধীন বাজার মডেল থেকেও আলাদা, উত্তর ইউরোপীয় উচ্চ কল্যাণ মডেল থেকেও আলাদা, বরং একটি মধ্যপথে এগিয়ে গেছে। অ্যাঙ্কার সিম্বায়োসিস সভ্যতা প্রতিষ্ঠার পর, এই মডেলটি সিম্বায়োসিস দর্শনের সাথে মিলিত হয়ে &quot;ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা&quot; নামক অনন্য সভ্যতার রূপটি তৈরি করেছে।</p><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার মূল দর্শনকে &quot;সামাজিক বাজার, মজুরি-মূলধন যৌথ সিদ্ধান্ত&quot; আটটি শব্দে সংক্ষিপ্ত করা যায়। সুনির্দিষ্টভাবে বলতে গেলে:</p><ol><li><strong>সামাজিক বাজার অর্থনীতি</strong>: বাজার ব্যবস্থার সম্পদ বণ্টনে মূল ভূমিকাকে স্বীকৃতি দেওয়ার সাথে সাথে, বাজারকে অবশ্যই সমাজের সামগ্রিক স্বার্থের জন্য কাজ করতে হবে বলেও জোর দেওয়া হয়। সামাজিক নীতির মাধ্যমে বাজারের ঘাটতি সংশোধন করে, অর্থনৈতিক কার্যকারিতা এবং সামাজিক ন্যায়বিচারের ভারসাম্য অর্জন করা হয়</li><li><strong>মজুরি-মূলধন যৌথ সিদ্ধান্ত</strong>: প্রতিষ্ঠান এবং সংস্থার পরিচালনায়, মজুরি এবং মূলধন পক্ষের যৌথ সিদ্ধান্তের ব্যবস্থা প্রয়োগ করা হয়। মজুরি ট্রেড ইউনিয়ন ইত্যাদি সংস্থার মাধ্যমে পরিচালনায় অংশগ্রহণ করে, নিজের অধিকার রক্ষা করে, এবং মজুরি-মূলধন উভয় পক্ষের সম্প্রীতিপূর্ণ সহাবস্থান অর্জন করে</li><li><strong>সমিতিবাদ</strong>: বিভিন্ন ধরনের সামাজিক সংস্থা (ট্রেড ইউনিয়ন, নিয়োগকর্তা সমিতি, শিল্প সমিতি ইত্যাদি) সামাজিক পরিচালনায় গুরুত্বপূর্ণ ভূমিকা পালন করে। রাষ্ট্র এবং সামাজিক সংস্থা আলোচনা ও সহযোগিতার মাধ্যমে সম্মিলিতভাবে নীতি প্রণয়ন করে এবং সমাজ পরিচালনা করে</li><li><strong>আলোচনামূলক গণতন্ত্র</strong>: গুরুত্বপূর্ণ সিদ্ধান্তে, সহজ সংখ্যাগরিষ্ঠ সিদ্ধান্তের পরিবর্তে ব্যাপক আলোচনা এবং সংলাপের মাধ্যমে ঐক্যমত্যে পৌঁছানোর উপর জোর দেওয়া হয়। সব পক্ষের স্বার্থের ভারসাম্য এবং সিদ্ধান্তের বৈধতার উপর গুরুত্ব দেওয়া হয়</li></ol><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার এই দর্শনগুলি অ্যাঙ্কার সিম্বায়োসিস সভ্যতার &quot;ব্যক্তি এবং সমষ্টির ভারসাম্য&quot; মূল দর্শনের সাথে অত্যন্ত মিলে যায়। সামাজিক বাজার অর্থনীতি কার্যকারিতা এবং ন্যায়বিচারের ভারসাম্য অর্জন করেছে, মজুরি-মূলধন যৌথ সিদ্ধান্ত মজুরি এবং পরিচালকদের ভারসাম্য অর্জন করেছে, এবং সমিতিবাদ এবং আলোচনামূলক গণতন্ত্র রাষ্ট্র এবং সমাজের ভারসাম্য অর্জন করেছে।</p><h2 id="_2-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-সামাজিক-কাঠামো" tabindex="-1">2. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সামাজিক কাঠামো <a class="header-anchor" href="#_2-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-সামাজিক-কাঠামো" aria-label="Permalink to &quot;2. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সামাজিক কাঠামো&quot;">​</a></h2><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সামাজিক কাঠামোর মূল বৈশিষ্ট্য হল &quot;সামাজিক বাজার রাষ্ট্র + সমিতিবাদী পরিচালনা + মজুরি-মূলধন যৌথ সিদ্ধান্ত ব্যবস্থা + আলোচনামূলক গণতন্ত্র সংস্কৃতি&quot;:</p><table tabindex="0"><thead><tr><th>কাঠামোর উপাদান</th><th>বৈশিষ্ট্যের বিবরণ</th><th>মূল কার্যকারিতা</th></tr></thead><tbody><tr><td>সামাজিক বাজার রাষ্ট্র</td><td>সরকার বাজার এবং সমাজের মধ্যে ভারসাম্যের ভূমিকা পালন করে, বাজারের শৃঙ্খলা রক্ষা করার সাথে সাথে সামাজিক সুরক্ষাও প্রদান করে</td><td>অর্থনৈতিক কার্যকারিতা এবং সামাজিক ন্যায়বিচারের ভারসাম্য অর্জন করা</td></tr><tr><td>সমিতিবাদী পরিচালনা</td><td>বিভিন্ন ধরনের সামাজিক সংস্থা রাষ্ট্রীয় পরিচালনায় গুরুত্বপূর্ণ ভূমিকা পালন করে, রাষ্ট্র এবং সমিতি আলোচনা ও সহযোগিতা করে</td><td>সব পক্ষের মতামত গ্রহণ করা, সিদ্ধান্তের মান এবং সামাজিক স্বীকৃতি বাড়ানো</td></tr><tr><td>মজুরি-মূলধন যৌথ সিদ্ধান্ত ব্যবস্থা</td><td>মজুরি ট্রেড ইউনিয়নের মাধ্যমে প্রতিষ্ঠান এবং সংস্থার পরিচালনার সিদ্ধান্তে অংশগ্রহণ করে</td><td>মজুরির অধিকার রক্ষা করা, মজুরি-মূলধন সম্প্রীতি অর্জন করা</td></tr><tr><td>আলোচনামূলক গণতন্ত্র সংস্কৃতি</td><td>গুরুত্বপূর্ণ সিদ্ধান্ত ব্যাপক আলোচনার মাধ্যমে ঐক্যমত্যে পৌঁছায়</td><td>সিদ্ধান্তের বৈধতা বাড়ানো, সামাজিক দ্বন্দ্ব কমানো</td></tr></tbody></table><h3 id="_2-1-সামাজিক-বাজার-রাষ্ট্র" tabindex="-1">2.1 সামাজিক বাজার রাষ্ট্র <a class="header-anchor" href="#_2-1-সামাজিক-বাজার-রাষ্ট্র" aria-label="Permalink to &quot;2.1 সামাজিক বাজার রাষ্ট্র&quot;">​</a></h3><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সরকার &quot;সামাজিক বাজার অর্থনীতি&quot; দর্শন মেনে চলে। উত্তর আমেরিকান বহুমুখী প্রকারের &quot;সীমিত সরকার&quot; থেকে ভিন্ন, সামাজিক বাজার রাষ্ট্রের সরকার অর্থনৈতিক এবং সামাজিক জীবনে আরও সক্রিয় ভূমিকা পালন করে:</p><ul><li><strong>বাজারের শৃঙ্খলা রক্ষা</strong>: সরকার আইন এবং নিয়ন্ত্রণের মাধ্যমে ন্যায়সঙ্গত প্রতিযোগিতার বাজার শৃঙ্খলা রক্ষা করে</li><li><strong>সামাজিক সুরক্ষা প্রদান</strong>: সরকার তুলনামূলকভাবে সম্পূর্ণ সামাজিক সুরক্ষা ব্যবস্থা প্রদান করে, যার মধ্যে বার্ধক্য, স্বাস্থ্য, বেকারত্ব, আবাসন ইত্যাদি অন্তর্ভুক্ত</li><li><strong>ম্যাক্রো অর্থনৈতিক নিয়ন্ত্রণ</strong>: সরকার আর্থিক এবং মুদ্রা নীতির মাধ্যমে সাধনা অর্থনীতির ম্যাক্রো নিয়ন্ত্রণ করে</li><li><strong>পাবলিক সেবা সরবরাহ</strong>: সরকার শিক্ষা, স্বাস্থ্য, মৌলিক অবকাঠামো ইত্যাদি পাবলিক সেবা প্রদান করে</li></ul><p>সামাজিক বাজার রাষ্ট্রের মূল দর্শন হল &quot;বাজার + সমাজ&quot; — বাজার কার্যকারিতার জন্য দায়ী, সমাজ ন্যায়বিচারের জন্য দায়ী, এবং উভয় একে অপরের পরিপূরক।</p><h3 id="_2-2-সমিতিবাদী-পরিচালনা" tabindex="-1">2.2 সমিতিবাদী পরিচালনা <a class="header-anchor" href="#_2-2-সমিতিবাদী-পরিচালনা" aria-label="Permalink to &quot;2.2 সমিতিবাদী পরিচালনা&quot;">​</a></h3><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা &quot;সমিতিবাদ&quot; পরিচালনা মডেল প্রয়োগ করে। বিভিন্ন ধরনের সামাজিক সংস্থা রাষ্ট্রীয় পরিচালনায় গুরুত্বপূর্ণ ভূমিকা পালন করে:</p><ul><li><strong>ট্রেড ইউনিয়ন সংস্থা</strong>: সাধনা মজুরির স্বার্থের প্রতিনিধিত্ব করে, নিয়োগকর্তা সমিতির সাথে সম্মিলিত আলোচনা করে, এবং শ্রম নীতি প্রণয়নে অংশগ্রহণ করে</li><li><strong>নিয়োগকর্তা সমিতি</strong>: সাধনা প্রতিষ্ঠান এবং উদ্যোক্তাদের স্বার্থের প্রতিনিধিত্ব করে, ট্রেড ইউনিয়নের সাথে সম্মিলিত আলোচনা করে, এবং অর্থনৈতিক নীতি প্রণয়নে অংশগ্রহণ করে</li><li><strong>শিল্প সমিতি</strong>: বিভিন্ন সাধনা শিল্পের স্বার্থের প্রতিনিধিত্ব করে, শিল্পের মানদণ্ড প্রণয়ন করে, এবং শিল্প নীতি প্রণয়নে অংশগ্রহণ করে</li><li><strong>ভোক্তা সংস্থা</strong>: সাধনা ভোক্তাদের স্বার্থের প্রতিনিধিত্ব করে, ভোক্তা সুরক্ষা নীতি প্রণয়নে অংশগ্রহণ করে</li></ul><p>সরকার গুরুত্বপূর্ণ নীতি প্রণয়নের সময়, সাধারণত সম্পর্কিত সামাজিক সংস্থাগুলিকে আলোচনার জন্য আমন্ত্রণ জানায়, সব পক্ষের মতামত শুনে, এবং শেষে সব পক্ষের জন্য গ্রহণযোগ্য সমাধান তৈরি করে। এই &quot;সমিতিবাদ&quot; পরিচালনা মডেল সিদ্ধান্তের মান এবং সামাজিক স্বীকৃতিকে ব্যাপকভাবে বাড়িয়েছে।</p><h3 id="_2-3-মজুরি-মূলধন-যৌথ-সিদ্ধান্ত-ব্যবস্থা" tabindex="-1">2.3 মজুরি-মূলধন যৌথ সিদ্ধান্ত ব্যবস্থা <a class="header-anchor" href="#_2-3-মজুরি-মূলধন-যৌথ-সিদ্ধান্ত-ব্যবস্থা" aria-label="Permalink to &quot;2.3 মজুরি-মূলধন যৌথ সিদ্ধান্ত ব্যবস্থা&quot;">​</a></h3><p>মজুরি-মূলধন যৌথ সিদ্ধান্ত হল ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সবচেয়ে বিশিষ্ট ব্যবস্থাগুলির মধ্যে একটি। সাধনা প্রতিষ্ঠান এবং কোম্পানিতে, মজুরি ট্রেড ইউনিয়নের প্রতিনিধিত্বের মাধ্যমে পরিচালনার সিদ্ধান্তে অংশগ্রহণ করে:</p><ul><li><strong>বোর্ড অব ডাইরেক্টর্সে যৌথ সিদ্ধান্ত</strong>: বড় সাধনা প্রতিষ্ঠানের বোর্ড অব ডাইরেক্টর্সে নির্দিষ্ট অনুপাতের মজুরি প্রতিনিধি রয়েছে, এবং মূলধন পক্ষের প্রতিনিধিদের সাথে যৌথভাবে সিদ্ধান্ত নেয়</li><li><strong>ওয়ার্ক কমিটি</strong>: প্রতিটি সাধনা প্রতিষ্ঠানে মজুরি দ্বারা নির্বাচিত ওয়ার্ক কমিটি রয়েছে, যা দৈনন্দিন পরিচালনার সিদ্ধান্তে অংশগ্রহণ করে</li><li><strong>সম্মিলিত আলোচনা</strong>: ট্রেড ইউনিয়ন এবং নিয়োগকর্তা সমিতি সাধকদের পারিশ্রমিক, কাজের শর্ত, সাধনা সম্পদ বণ্টন ইত্যাদি নিয়ে সম্মিলিত আলোচনা করে</li></ul><p>মজুরি-মূলধন যৌথ সিদ্ধান্ত ব্যবস্থা সাধনা মজুরির অধিকারকে সুরক্ষিত করে, এবং মজুরিকে আর নিষ্ক্রিয় &quot;পরিচালিত ব্যক্তি&quot; না হয়ে সক্রিয় &quot;অংশগ্রহণকারী&quot; করে তুলেছে। এটি মজুরির উৎসাহ এবং প্রতিষ্ঠানের প্রতি পরিচয়বোধকে ব্যাপকভাবে বাড়িয়েছে, এবং মজুরি-মূলধন উভয় পক্ষের সম্প্রীতিপূর্ণ সহাবস্থান অর্জন করেছে।</p><h3 id="_2-4-আলোচনামূলক-গণতন্ত্র-সংস্কৃতি" tabindex="-1">2.4 আলোচনামূলক গণতন্ত্র সংস্কৃতি <a class="header-anchor" href="#_2-4-আলোচনামূলক-গণতন্ত্র-সংস্কৃতি" aria-label="Permalink to &quot;2.4 আলোচনামূলক গণতন্ত্র সংস্কৃতি&quot;">​</a></h3><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার গভীর আলোচনামূলক গণতন্ত্র সংস্কৃতি রয়েছে। গুরুত্বপূর্ণ সিদ্ধান্ত সহজভাবে সংখ্যাগরিষ্ঠ ভোটে নির্ধারিত হয় না, বরং ব্যাপক আলোচনা এবং সংলাপের মাধ্যমে যতটা সম্ভব সব পক্ষের জন্য গ্রহণযোগ্য ঐক্যমত্যে পৌঁছায়:</p><ul><li><strong>বহুপক্ষীয় আলোচনা</strong>: সরকার, ট্রেড ইউনিয়ন, নিয়োগকর্তা সমিতি, ভোক্তা সংস্থা ইত্যাদি সব পক্ষ একসাথে বসে পূর্ণাঙ্গ আলোচনা এবং পরামর্শ করে</li><li><strong>স্বার্থের ভারসাম্য</strong>: আলোচনায় সব পক্ষের যুক্তিসঙ্গত স্বার্থকে পূর্ণাঙ্গভাবে বিবেচনা করে, এবং সর্বাধিক সাধারণ ভাগিতল খোঁজা হয়</li><li><strong>ঐক্যমত্য অগ্রাধিকার</strong>: যতটা সম্ভব ঐক্যমত্যে পৌঁছানোর চেষ্টা করা হয়, এবং শুধুমাত্র ঐক্যমত্যে পৌঁছাতে অক্ষম হলেই ভোট দেওয়া হয়</li><li><strong>স্বচ্ছ ও প্রকাশ্য</strong>: আলোচনার প্রক্রিয়া স্বচ্ছ ও প্রকাশ্য, এবং সামাজিক তত্ত্বাবধান গ্রহণ করে</li></ul><p>আলোচনামূলক গণতন্ত্র সংস্কৃতি যদিও সিদ্ধান্তের কার্যকারিতা তুলনামূলকভাবে কম, কিন্তু সিদ্ধান্তের মান এবং সামাজিক স্বীকৃতি বেশি, এবং কার্যকর করাও আরও সহজ হয়।</p><h2 id="_3-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-সাধনা-মডেল" tabindex="-1">3. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সাধনা মডেল <a class="header-anchor" href="#_3-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-সাধনা-মডেল" aria-label="Permalink to &quot;3. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সাধনা মডেল&quot;">​</a></h2><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সাধনা মডেলের মূল বৈশিষ্ট্য হল &quot;দ্বি-রেল ব্যবস্থা, শিক্ষা-প্রতিষ্ঠান সহযোগিতা, মজুরি-মূলধন সম্প্রীতি&quot;:</p><h3 id="_3-1-দ্বি-রেল-ব্যবস্থার-সাধনা-শিক্ষা" tabindex="-1">3.1 দ্বি-রেল ব্যবস্থার সাধনা শিক্ষা <a class="header-anchor" href="#_3-1-দ্বি-রেল-ব্যবস্থার-সাধনা-শিক্ষা" aria-label="Permalink to &quot;3.1 দ্বি-রেল ব্যবস্থার সাধনা শিক্ষা&quot;">​</a></h3><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা &quot;দ্বি-রেল ব্যবস্থা&quot; সাধনা শিক্ষা প্রয়োগ করে:</p><ul><li><strong>তাত্ত্বিক রেল</strong>: সাধক সাধনা কলেজে সাধনা তত্ত্ব এবং মৌলিক জ্ঞান শেখে</li><li><strong>ব্যবহারিক রেল</strong>: সাধক সাধনা প্রতিষ্ঠানে ব্যবহারিক সাধনা করে, এবং বাস্তব অভিজ্ঞতা অর্জন করে</li></ul><p>সাধক সপ্তাহে কিছু সময় কলেজে তত্ত্ব শেখে, কিছু সময় প্রতিষ্ঠানে ব্যবহারিক কাজ করে। এই &quot;দ্বি-রেল ব্যবস্থা&quot; সাধকদের শক্তিশালী তাত্ত্বিক ভিত্তি দখল করতে এবং সমৃদ্ধ ব্যবহারিক অভিজ্ঞতা অর্জন করতে সক্ষম করে, এবং স্নাতক হওয়ার পর দ্রুত বাস্তব কাজের সাথে খাপ খাইয়ে নিতে পারে।</p><h3 id="_3-2-শিক্ষা-প্রতিষ্ঠান-সহযোগিতা" tabindex="-1">3.2 শিক্ষা-প্রতিষ্ঠান সহযোগিতা <a class="header-anchor" href="#_3-2-শিক্ষা-প্রতিষ্ঠান-সহযোগিতা" aria-label="Permalink to &quot;3.2 শিক্ষা-প্রতিষ্ঠান সহযোগিতা&quot;">​</a></h3><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সাধনা কলেজ এবং সাধনা প্রতিষ্ঠানের মধ্যে ঘনিষ্ঠ সহযোগিতার সম্পর্ক রয়েছে:</p><ul><li>প্রতিষ্ঠান কলেজের কোর্স ডিজাইনে অংশগ্রহণ করে, এবং শিক্ষণের বিষয়বস্তু বাস্তব চাহিদার সাথে মানানসই করে</li><li>প্রতিষ্ঠান কলেজের জন্য ব্যবহারিক জায়গা এবং প্রশিক্ষক প্রদান করে</li><li>কলেজ প্রতিষ্ঠানের জন্য কাস্টমাইজড সাধনা প্রতিভা প্রশিক্ষণ দেয়</li><li>কলেজ এবং প্রতিষ্ঠান সহযোগিতা করে সাধনা প্রযুক্তির গবেষণা ও উন্নয়ন করে</li></ul><p>এই শিক্ষা-প্রতিষ্ঠান সহযোগিতা মডেল সাধনা প্রতিভার প্রশিক্ষণের মান এবং কর্মসংস্থানের মানানসইতাকে ব্যাপকভাবে বাড়িয়েছে।</p><h3 id="_3-3-মজুরি-মূলধন-সম্প্রীতির-সাধনা-পরিবেশ" tabindex="-1">3.3 মজুরি-মূলধন সম্প্রীতির সাধনা পরিবেশ <a class="header-anchor" href="#_3-3-মজুরি-মূলধন-সম্প্রীতির-সাধনা-পরিবেশ" aria-label="Permalink to &quot;3.3 মজুরি-মূলধন সম্প্রীতির সাধনা পরিবেশ&quot;">​</a></h3><p>মজুরি-মূলধন যৌথ সিদ্ধান্ত ব্যবস্থার অধীনে, ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সাধনা প্রতিষ্ঠানের অভ্যন্তরে মজুরি-মূলধন সম্পর্ক সম্প্রীতিপূর্ণ:</p><ul><li>সাধকদের প্রতিষ্ঠান পরিচালনায় অংশগ্রহণ করার পর্যাপ্ত কথা বলার অধিকার রয়েছে</li><li>সাধকদের পারিশ্রমিক এবং কাজের শর্ত সম্মিলিত আলোচনার মাধ্যমে নির্ধারিত হয়, এবং পর্যাপ্ত সুরক্ষা রয়েছে</li><li>সাধক এবং পরিচালকদের মধ্যে সহযোগিতার সম্পর্ক, বিরোধিতার সম্পর্ক নয়</li><li>সাধকদের প্রতিষ্ঠানের প্রতি উচ্চ পরিচয়বোধ এবং অন্তর্ভুক্তির অনুভূতি রয়েছে</li></ul><p>এই সম্প্রীতিপূর্ণ সাধনা পরিবেশ সাধকদের শান্তভাবে সাধনা করতে সক্ষম করে, এবং অধিকারের সমস্যায় মন নষ্ট করতে হয় না।</p><h3 id="_3-4-স্থিতিশীল-সাধনা-পেশাগত-উন্নয়ন" tabindex="-1">3.4 স্থিতিশীল সাধনা পেশাগত উন্নয়ন <a class="header-anchor" href="#_3-4-স্থিতিশীল-সাধনা-পেশাগত-উন্নয়ন" aria-label="Permalink to &quot;3.4 স্থিতিশীল সাধনা পেশাগত উন্নয়ন&quot;">​</a></h3><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা সাধকদের দীর্ঘমেয়াদী পেশাগত উন্নয়নের উপর গুরুত্ব দেয়:</p><ul><li>সাধক সাধারণত একটি প্রতিষ্ঠানে দীর্ঘমেয়াদী উন্নয়ন করে, এবং চলাচল কম</li><li>প্রতিষ্ঠান সাধকদের জন্য ক্রমাগত প্রশিক্ষণ এবং পদোন্নতির সুযোগ প্রদান করে</li><li>সাধকদের পারিশ্রমিক অভিজ্ঞতা এবং ক্ষমতার সাথে সাথে ক্রমাগত বৃদ্ধি পায়</li><li>সম্পূর্ণ পেশাগত যোগ্যতা সনদ ব্যবস্থা রয়েছে, এবং সাধকদের পেশাগত উন্নয়নকে সুরক্ষিত করে</li></ul><h2 id="_4-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-চুক্তিভিত্তিক-উৎপাদন-ব্যবস্থা" tabindex="-1">4. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার চুক্তিভিত্তিক উৎপাদন ব্যবস্থা <a class="header-anchor" href="#_4-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-চুক্তিভিত্তিক-উৎপাদন-ব্যবস্থা" aria-label="Permalink to &quot;4. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার চুক্তিভিত্তিক উৎপাদন ব্যবস্থা&quot;">​</a></h2><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার চুক্তিভিত্তিক উৎপাদন ব্যবস্থা &quot;সামাজিক অংশীদারিত্ব চুক্তি&quot; কে প্রধান রূপ হিসেবে গ্রহণ করে:</p><ol><li><strong>ত্রিপক্ষীয় আলোচনা</strong>: সম্পদ বণ্টনের পরিকল্পনা সরকার, ট্রেড ইউনিয়ন, নিয়োগকর্তা সমিতি ত্রিপক্ষীয় আলোচনার মাধ্যমে নির্ধারিত হয়, সরকারের একতরফা সিদ্ধান্ত দ্বারা নয়</li><li><strong>সম্মিলিত চুক্তি</strong>: সাধকদের পারিশ্রমিক এবং সম্পদ বণ্টন সম্মিলিত চুক্তির মাধ্যমে নির্ধারিত হয়, এবং মজুরি-মূলধন উভয় পক্ষের জন্য বাধ্যতামূলক</li><li><strong>যৌথ সিদ্ধান্ত বণ্টন</strong>: সাধনা প্রতিষ্ঠানের অভ্যন্তরে সম্পদ বণ্টন মজুরি-মূলধন উভয় পক্ষের যৌথ সিদ্ধান্ত দ্বারা নির্ধারিত হয়</li><li><strong>সামাজিক অংশীদারিত্ব সম্পর্ক</strong>: সরকার, ট্রেড ইউনিয়ন, নিয়োগকর্তা সমিতির মধ্যে দীর্ঘমেয়াদী সামাজিক অংশীদারিত্ব সম্পর্ক স্থাপন করে, এবং সম্মিলিতভাবে সভ্যতার উন্নয়নকে এগিয়ে নেয়</li></ol><p>এই &quot;সামাজিক অংশীদারিত্ব চুক্তি&quot; ব্যবস্থার সুবিধা হল মজুরি-মূলধন সম্প্রীতি, সামাজিক স্থিতিশীলতা, সিদ্ধান্তের মান উচ্চ, কিন্তু সিদ্ধান্তের কার্যকারিতা বাড়ানো, এবং অতিরিক্ত আলোচনার কারণে উন্নয়নের সুযোগ হারানো এড়ানোও দরকার।</p><h2 id="_5-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-সুবিধা-এবং-চ্যালেঞ্জ" tabindex="-1">5. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সুবিধা এবং চ্যালেঞ্জ <a class="header-anchor" href="#_5-ইউরোপীয়-মহাদেশীয়-সামাজিক-প্রকার-সভ্যতার-সুবিধা-এবং-চ্যালেঞ্জ" aria-label="Permalink to &quot;5. ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতার সুবিধা এবং চ্যালেঞ্জ&quot;">​</a></h2><h3 id="_5-1-সাধারণ-সুবিধা" tabindex="-1">5.1 সাধারণ সুবিধা <a class="header-anchor" href="#_5-1-সাধারণ-সুবিধা" aria-label="Permalink to &quot;5.1 সাধারণ সুবিধা&quot;">​</a></h3><ul><li><strong>শক্তিশালী স্থিতিশীলতা</strong>: মজুরি-মূলধন যৌথ সিদ্ধান্ত এবং সমিতিবাদ উচ্চ স্তরের সামাজিক স্থিতিশীলতা আনেছে</li><li><strong>উচ্চ ঐক্যবদ্ধতা</strong>: আলোচনামূলক গণতন্ত্র এবং সামাজিক অংশীদারিত্ব সম্পর্ক সামাজিক ঐক্যবদ্ধতা বাড়িয়েছে</li><li><strong>মজুরি-মূলধন সম্প্রীতি</strong>: মজুরির অধিকার পর্যাপ্তভাবে সুরক্ষিত, এবং মজুরি-মূলধন সম্পর্ক সম্প্রীতিপূর্ণ</li><li><strong>উচ্চ মানের</strong>: দ্বি-রেল ব্যবস্থার শিক্ষা এবং শিক্ষা-প্রতিষ্ঠান সহযোগিতা উচ্চ মানের সাধনা প্রতিভা প্রশিক্ষণ দিয়েছে</li></ul><h3 id="_5-2-মুখোমুখি-চ্যালেঞ্জ" tabindex="-1">5.2 মুখোমুখি চ্যালেঞ্জ <a class="header-anchor" href="#_5-2-মুখোমুখি-চ্যালেঞ্জ" aria-label="Permalink to &quot;5.2 মুখোমুখি চ্যালেঞ্জ&quot;">​</a></h3><ul><li><strong>প্রশাসনিক কার্যকারিতা কম</strong>: অতিরিক্ত আলোচনা সিদ্ধান্ত ধীর এবং প্রশাসনিক কার্যকারিতা কম হতে পারে</li><li><strong>উদ্ভাবনী প্রাণশক্তি অপর্যাপ্ত</strong>: তুলনামূলকভাবে রক্ষণশীল সংস্কৃতি উদ্ভাবনী প্রাণশক্তিকে প্রভাবিত করতে পারে</li><li><strong>শ্রম বাজারের অনমনীয়তা</strong>: কঠোর শ্রম সুরক্ষা শ্রম বাজারকে পর্যাপ্ত নমনীয় না হতে পারে</li><li><strong>আর্থিক চাপ বেশি</strong>: তুলনামূলকভাবে সম্পূর্ণ সামাজিক সুরক্ষা ব্যবস্থা বেশি আর্থিক চাপ আনেছে</li></ul><p>এই চ্যালেঞ্জগুলির মোকাবেলায়, ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা সক্রিয়ভাবে অন্য টাইপোলজিগুলির সুবিধা গ্রহণ করছে, যেমন উত্তর আমেরিকান বহুমুখী প্রকারের উদ্ভাবনী প্রেরণা ব্যবস্থা, পূর্ব এশীয় ঘনীভূত প্রকারের কার্যকারিতা ব্যবস্থা ইত্যাদি প্রবর্তন করছে, এবং সামাজিক স্থিতিশীলতা এবং মজুরি-মূলধন সম্প্রীতির বৈশিষ্ট্য বজায় রাখার সময় উন্নয়নের কার্যকারিতা এবং উদ্ভাবনী প্রাণশক্তি বাড়াচ্ছে।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতা হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার মধ্যে সবচেয়ে ভারসাম্যপূর্ণ জ্ঞানের সভ্যতার টাইপোলজি। এটি &quot;সামাজিক বাজার, মজুরি-মূলধন যৌথ সিদ্ধান্ত&quot; কে মূল দর্শন হিসেবে গ্রহণ করে, এবং সামাজিক বাজার রাষ্ট্র, সমিতিবাদী পরিচালনা, মজুরি-মূলধন যৌথ সিদ্ধান্ত ব্যবস্থা, আলোচনামূলক গণতন্ত্র সংস্কৃতির সামাজিক কাঠামো, দ্বি-রেল ব্যবস্থা, শিক্ষা-প্রতিষ্ঠান সহযোগিতা, মজুরি-মূলধন সম্প্রীতির সাধনা মডেল, এবং সামাজিক অংশীদারিত্ব চুক্তির উৎপাদন ব্যবস্থার মাধ্যমে কার্যকারিতা এবং ন্যায়বিচার, বাজার এবং সমাজ, মজুরি এবং মূলধনের ভালো ভারসাম্য অর্জন করেছে। নিজের বৈশিষ্ট্য বজায় রাখার পাশাপাশি, ইউরোপীয় মহাদেশীয় সামাজিক প্রকার সভ্যতাও ক্রমাগত স্থিতিশীলতা এবং কার্যকারিতা, আলোচনা এবং সিদ্ধান্তের মধ্যে সেরা ভারসাম্যের বিন্দু খুঁজছে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (পাঁচ ধরনের সিম্বায়োসিস সভ্যতার টাইপোলজির সংক্ষিপ্ত বিবরণ)</li><li>36-社会结构与阶层流动 (সামাজিক কাঠামো এবং শ্রেণী চলাচল)</li><li>41-共生劳动法 (সিম্বায়োসিস শ্রম আইন)</li></ul>',57)])])}const _=a(i,[["render",e]]);export{g as __pageData,_ as default};
